            "ਉਹ ਨਿਮਰ ਸੁਭਾਅ ਦੀ ਸੀ; ਇੱਕ ਵਾਰ ਪੰਜ ਮੈਡਲ ਜਿੱਤ ਕੇ ਵੀ ਉਸ ਨੇ ਘਰਦਿਆਂ ਨੂੰ ਸਿਰਫ਼ ਇਹੀ ਦੱਸਿਆ ਕਿ ਮੁਕਾਬਲਾ ਠੀਕ ਰਿਹਾ।",
